// discouraged: expressible, but this is what Rust code reaches for instead
enum Shape { Circle(Circle), Union(Box<Shape>, Box<Shape>) }

fn area(s: &Shape) -> f64 {          // exhaustive: a new variant breaks this at compile time
    match s {
        Shape::Circle(c) => std::f64::consts::PI * c.r * c.r,
        Shape::Union(a, b) => area(a) + area(b),
    }
}
